\begin{lemma}[A 3-dimensional ancient solution has $\operatorname{Rm}\geq0$]
\label{lem:chow-ii-appd-ancient-three-dimensional-nonnegative}
\source{chow-et-al-ricci-flow-part-ii:page-0393}
\uses{thm:chow-ii-appd-hamilton-ivey}
\dcref{appD:D.20}
\group{Curvature Pinching}


Every complete three-dimensional ancient Ricci flow with bounded curvature
has nonnegative sectional curvature.
\end{lemma}

